def solve(x):
    if not x:
        return []
    result = []
    current_count = 1
    current_value = x[0]
    for i in range(1, len(x)):
        if x[i] == current_value:
            current_count += 1
        else:
            result.append([current_count, current_value])
            current_value = x[i]
            current_count = 1
    result.append([current_count, current_value])
    return result
